### ✅ C++ 代码（带详细注释）

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <sstream>
#include <thread>
#include <mutex>
#include <chrono>
#include <ctime>
#include <algorithm>
#include <string>
#include <mutex>
#include <atomic>

using namespace std;

// 模拟数据处理函数：读取文件、清洗、处理、存储和生成报表
void process_file(const string& file_path, const string& file_type, 
                 mutex& mtx, atomic<int>& processed_count) {
    // 1. 打开文件并读取内容
    ifstream file(file_path);
    if (!file.is_open()) {
        cerr << "Error: Could not open file " << file_path << endl;
        return;
    }

    vector<string> data;
    string line;
    while (getline(file, line)) {
        data.push_back(line);
    }
    file.close();

    // 2. 模拟数据清洗和预处理
    // a. 去重（简单模拟：删除重复行）
    auto last = unique(data.begin(), data.end());
    data.erase(last, data.end());

    // b. 缺失值处理（模拟：跳过空行）
    data.erase(remove_if(data.begin(), data.end(), [](const string& s) { return s.empty(); }), data.end());

    // c. 时间格式统一（模拟：只处理包含"timestamp"的行）
    for (auto& row : data) {
        if (row.find("timestamp") != string::npos) {
            // 这里可以加入更复杂的时间格式转换逻辑
        }
    }

    // d. 文本标准化（模拟：去除特殊符号、分词）
    for (auto& row : data) {
        if (row.find("message") != string::npos) {
            // 去除特殊符号
            row.erase(remove_if(row.begin(), row.end(), 
                               [](char c) { return !isalnum(c) && !isspace(c); }), 
                      row.end());
            // 转为小写
            transform(row.begin(), row.end(), row.begin(), ::tolower);
            // 模拟分词（简单按空格分割）
            // 这里可以替换为更复杂的分词逻辑
        }
    }

    // 3. 模拟存储到数据库（此处仅为模拟）
    // 实际项目中应使用数据库连接库（如 libpqxx、MySQL++）实现
    cout << "Stored data from: " << file_path << endl;

    // 4. 模拟生成报表（此处仅为模拟）
    cout << "Generated report for: " << file_path << endl;

    // 5. 更新处理计数器（使用原子变量保证线程安全）
    lock_guard<mutex> lock(mtx);
    processed_count++;
    cout << "Processed: " << file_path << endl;
}

int main() {
    // 1. 定义可配置参数（模拟）
    vector<string> files = {"file1.csv", "file2.json"};
    mutex mtx;
    atomic<int> processed_count(0);

    // 2. 模拟多线程处理（使用 C++11 的 thread）
    vector<thread> threads;
    for (const auto& file : files) {
        threads.emplace_back(process_file, file, ref(mtx), ref(processed_count));
    }

    // 3. 等待所有线程完成
    for (auto& t : threads) {
        t.join();
    }

    // 4. 输出最终处理结果
    cout << "Total processed files: " << processed_count.load() << endl;

    return 0;
}
```

