### 🧾 コード（300行以内、コメント付き）

```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <string>
#include <thread>
#include <mutex>
#include <chrono>
#include <sstream>
#include <algorithm>
#include <cctype>

using namespace std;

mutex mtx; // ロック用ミューテックス

/**
 * @brief テキストのクリーニング処理
 * - 特殊文字を削除
 * - 小文字に変換
 * - 空白を含む文字列を保持
 * @param text 変換対象の文字列
 */
void cleanText(string& text) {
    text.erase(remove_if(text.begin(), text.end(), [](char c) { return !isalnum(c) && !isspace(c); }), text.end());
    transform(text.begin(), text.end(), text.begin(), ::tolower);
}

/**
 * @brief サポートチャットファイルの処理
 * - ファイルを読み込み、平均応答時間を計算
 * - テキストクリーニングと単語分割を実施
 * @param file ファイルパス
 */
void processSupportFile(string file) {
    ifstream fin(file);
    if (!fin) return;
    string line;
    map<string, int> sentiment;
    double avgResp = 0.0;
    int count = 0;

    while (getline(fin, line)) {
        vector<string> tokens;
        istringstream iss(line);
        string word;
        while (iss >> word) tokens.push_back(word);
        cleanText(line);
        avgResp += stod(tokens[1]);
        count++;
    }

    avgResp /= count;
    cout << "Processed: " << file << " - Avg Resp: " << avgResp << endl;
}

/**
 * @brief 取引データファイルの処理
 * - 日次売上、購入頻度、人気製品の統計を計算
 * @param file ファイルパス
 */
void processTransactionFile(string file) {
    ifstream fin(file);
    if (!fin) return;
    map<string, double> sales;
    map<string, int> freq;
    map<string, int> products;

    string line;
    while (getline(fin, line)) {
        istringstream iss(line);
        string date, amount, user, product;
        iss >> date >> amount >> user >> product;
        sales[date] += stod(amount);
        freq[user]++;
        products[product]++;
    }

    cout << "Processed: " << file << " - Sales: " << sales.size() << endl;
}

/**
 * @brief ファイルをマルチスレッドで処理
 * - ファイルリストを生成し、それぞれをスレッドに割り当て
 * @note 仮想ファイル名を使用（実際にはデータディレクトリから読み込む）
 */
void processFiles() {
    vector<string> files;
    for (int i = 0; i < 10; i++) files.push_back("data_" + to_string(i) + ".txt");

    vector<thread> threads;
    for (auto& file : files) {
        threads.emplace_back([file] { processSupportFile(file); });
        threads.emplace_back([file] { processTransactionFile(file); });
    }

    for (auto& t : threads) t.join();
    cout << "Processing complete." << endl;
}

/**
 * @brief メイン関数
 * - プログラムのエントリポイント
 * - プロセス開始と終了時間を計測
 */
int main() {
    auto start = chrono::steady_clock::now();
    processFiles();
    auto end = chrono::steady_clock::now();
    cout << "Total time: " << chrono::duration_cast<chrono::seconds>(end - start).count() << "s" << endl;
    return 0;
}
```

---

### 📌 コードの全体的な論理（コメント付き）

1. **`cleanText`**:
   - テキストをクリーニングし、特殊文字を削除、小文字に変換、単語分割を実施。
   - これにより、後続の分析処理に必要な形式にデータを変換。

2. **`processSupportFile`**:
   - サポートチャットファイルを読み込み、平均応答時間を計算。
   - 各行を単語に分割し、テキストクリーニングを実施。

3. **`processTransactionFile`**:
   - 取引データファイルを読み込み、日次売上、購入頻度、人気製品の統計を計算。
   - `map` を使ってデータを集計。

4. **`processFiles`**:
   - ファイルリストを生成し、それぞれをスレッドに割り当てて並列処理。
   - マルチスレッド処理により、大規模なデータ処理を効率化。

5. **`main`**:
   - プログラムのエントリポイント。
   - 処理開始と終了時間を計測し、処理時間の出力。

