### ✅ **C++ Code (Under 300 Lines)**

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>
#include <unordered_map>
#include <algorithm>
#include <ctime>
#include <regex>
#include <filesystem>
#include <nlohmann/json.hpp>
#include <sqlite3.h>

using json = nlohmann::json;

// Data cleaning and preprocessing
std::vector<std::map<std::string, std::string>> clean_data(const std::vector<std::map<std::string, std::string>>& data) {
    std::vector<std::map<std::string, std::string>> cleaned;
    for (auto& item : data) {
        std::map<std::string, std::string> cleaned_item = item;
        // Remove special characters and lowercase
        cleaned_item["text"] = std::regex_replace(cleaned_item["text"], std::regex(R"([^\w\s])"), "");
        std::transform(cleaned_item["text"].begin(), cleaned_item["text"].end(), cleaned_item["text"].begin(), ::tolower);
        cleaned.push_back(cleaned_item);
    }
    return cleaned;
}

// Read CSV
std::vector<std::map<std::string, std::string>> read_csv(const std::string& path) {
    std::ifstream file(path);
    std::vector<std::map<std::string, std::string>> data;
    if (!file.is_open()) return data;

    std::string line;
    std::getline(file, line);
    std::stringstream ss(line);
    std::string header;
    std::getline(ss, header, ',');
    while (std::getline(file, line)) {
        std::stringstream line_ss(line);
        std::string field;
        std::map<std::string, std::string> row;
        int col = 0;
        while (std::getline(line_ss, field, ',')) {
            row[header[col++]] = field;
        }
        data.push_back(row);
    }
    return data;
}

// Read JSON
std::vector<std::map<std::string, std::string>> read_json(const std::string& path) {
    std::ifstream file(path);
    json j;
    file >> j;
    std::vector<std::map<std::string, std::string>> data;
    for (auto& item : j) {
        std::map<std::string, std::string> row;
        for (auto& [k, v] : item.items()) {
            row[k] = v;
        }
        data.push_back(row);
    }
    return data;
}

// Main logic
int main() {
    std::filesystem::create_directories("output");
    std::vector<std::map<std::string, std::string>> processed_chats, daily_sales;
    std::string data_dir = "data";
    std::cout << "Processing data..." << std::endl;

    for (const auto& entry : std::filesystem::directory_iterator(data_dir)) {
        std::string path = entry.path().string();
        std::vector<std::map<std::string, std::string>> data;
        if (path.substr(path.find_last_of(".") + 1) == "csv") {
            data = read_csv(path);
        } else if (path.substr(path.find_last_of(".") + 1) == "json") {
            data = read_json(path);
        }
        data = clean_data(data);
        // Process and store data (simplified)
        std::cout << "Processed " << data.size() << " records from " << path << std::endl;
    }

    std::cout << "Data processing completed." << std::endl;
    return 0;
}
```

